#include <stdint.h>

#include "stm32f407xx.h"

extern uint32_t systemTimeCounter;


void delayMs(uint32_t delay)
{
	uint32_t curr = systemTimeCounter;
	while(systemTimeCounter - curr < delay)
	{	}
}



int main(void)
{
	// PWR AND SYS ENABLE
	RCC->APB2ENR |= RCC_APB2ENR_SYSCFGEN;
	RCC->APB1ENR |= RCC_APB1ENR_PWREN;
	PWR->CSR |= PWR_CSR_VOSRDY;

	SysTick_Config(16000000/1000);
	NVIC_SetPriority(SysTick_IRQn,0);
	NVIC_EnableIRQ(SysTick_IRQn);

	// switches
		RCC->AHB1ENR |= RCC_AHB1ENR_GPIOAEN;
		GPIOA->MODER &= ~((3 << GPIO_MODER_MODE0_Pos)|(3 << GPIO_MODER_MODE1_Pos));
		GPIOA->MODER &= ~((3 << GPIO_MODER_MODE2_Pos)|(3 << GPIO_MODER_MODE3_Pos));

		//LEDs
		RCC->AHB1ENR |= RCC_AHB1ENR_GPIOCEN | RCC_AHB1ENR_GPIOCEN;
		GPIOC->MODER &= ~((3 << GPIO_MODER_MODE0_Pos)|(3 << GPIO_MODER_MODE1_Pos));
		GPIOC->MODER &= ~((3 << GPIO_MODER_MODE2_Pos)|(3 << GPIO_MODER_MODE3_Pos));

		GPIOC->MODER |= ((1 << GPIO_MODER_MODE0_Pos)|(1 << GPIO_MODER_MODE1_Pos));
		GPIOC->MODER |= ((1 << GPIO_MODER_MODE2_Pos)|(1 << GPIO_MODER_MODE3_Pos));

		// USART
		RCC->AHB1ENR |= RCC_AHB1ENR_GPIOAEN;
		GPIOA->MODER &= ~((3 << GPIO_MODER_MODE9_Pos)| (3 <<GPIO_MODER_MODE10_Pos ));
		GPIOA->MODER |= (2 << GPIO_MODER_MODE9_Pos)| (2 <<GPIO_MODER_MODE10_Pos );
		GPIOA->OSPEEDR |=  GPIO_OSPEEDER_OSPEEDR9 | GPIO_OSPEEDER_OSPEEDR10;
		GPIOA->AFR[1] |= (7 << GPIO_AFRH_AFSEL9_Pos) | (7 << GPIO_AFRH_AFSEL10_Pos);

		RCC->APB2ENR |= RCC_APB2ENR_USART1EN;



		USART1->CR1 &= ~(USART_CR1_M);
		USART1->CR1 |= USART_CR1_OVER8;
		USART1->BRR |= 0XD03;  //4800  //VALUE_TO_WRITE;
		USART1->CR2 &= ~(USART_CR2_STOP);
		USART1->CR1 |= USART_CR1_UE;
		USART1->CR1 |= USART_CR1_TE | USART_CR1_RE;

		char str[] = "abcde";
		for(int i =0; str[i];i++)
		{
			while(!(USART1->SR & USART_SR_TXE));
			USART1->DR = str[i];
		}

  uint8_t mode;
  char symbol;
  while (1)
  {

//	  delayMs(1000);
	if (!(GPIOA->IDR & GPIO_IDR_ID0)){
		mode = 1;
		GPIOC->ODR &= ~(GPIO_ODR_OD0);
		GPIOC->ODR |= (GPIO_ODR_OD1);
		GPIOC->ODR |= (GPIO_ODR_OD2);
		GPIOC->ODR |= (GPIO_ODR_OD3);
	}

	if (!(GPIOA->IDR & GPIO_IDR_ID1)){
			mode = 2;
			GPIOC->ODR |= (GPIO_ODR_OD0);
			GPIOC->ODR &= ~(GPIO_ODR_OD1);
			GPIOC->ODR |= (GPIO_ODR_OD2);
			GPIOC->ODR |= (GPIO_ODR_OD3);
		}

	if (!(GPIOA->IDR & GPIO_IDR_ID2)){
			mode = 3;
			GPIOC->ODR |= (GPIO_ODR_OD0);
			GPIOC->ODR |= (GPIO_ODR_OD1);
			GPIOC->ODR &= ~(GPIO_ODR_OD2);
			GPIOC->ODR |= (GPIO_ODR_OD3);
		}

	if (!(GPIOA->IDR & GPIO_IDR_ID3)){
			mode = 4;
			GPIOC->ODR |= (GPIO_ODR_OD0);
			GPIOC->ODR |= (GPIO_ODR_OD1);
			GPIOC->ODR |= (GPIO_ODR_OD2);
			GPIOC->ODR &= ~(GPIO_ODR_OD3);
		}
	if (mode == 1){
		while (!(USART1->SR & USART_SR_RXNE));
			symbol = USART1->DR;
			while(!(USART1->SR & USART_SR_TXE));
			USART1->DR = symbol;

	}
	if (mode == 2){
			while (!(USART1->SR & USART_SR_RXNE)){
				symbol = USART1->DR;
				while (!(GPIOA->IDR & GPIO_IDR_ID1)){
					while(!(USART1->SR & USART_SR_TXE));
					USART1->DR = symbol;
				}
			}
		}
	if (mode == 3){
				while (!(USART1->SR & USART_SR_RXNE)){
					symbol = USART1->DR;
					while (!(GPIOA->IDR & GPIO_IDR_ID1)){
					while(!(USART1->SR & USART_SR_TXE));
					USART1->DR = symbol;
					}
				}
			}

//	USART1->DR = mode;

  }

}
